import torch
import torch.nn as nn
import math
from torch.utils.cpp_extension import load_inline

custom_cuda_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void linear_relu_div_kernel(
    const float* __restrict__ x,
    const float* __restrict__ w,
    const float* __restrict__ b,
    float* __restrict__ out,
    int batch_size,
    int in_features,
    int out_features,
    float divisor
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = batch_size * out_features;
    if (idx < total) {
        int i = idx / out_features;
        int j = idx % out_features;
        float val = 0.0f;
        for (int k = 0; k < in_features; k++) {
            val += x[i * in_features + k] * w[j * in_features + k];
        }
        val += b[j];
        val = val > 0.f ? val : 0.f;
        val /= divisor;
        out[idx] = val;
    }
}

torch::Tensor linear_relu_div_cuda(
    torch::Tensor x,
    torch::Tensor w,
    torch::Tensor b,
    float divisor
) {
    auto batch_size = x.size(0);
    auto in_features = x.size(1);
    auto out_features = w.size(0);
    auto out = torch::empty({batch_size, out_features}, x.options());

    int block_size = 256;
    int total = batch_size * out_features;
    int grid_size = (total + block_size - 1) / block_size;

    linear_relu_div_kernel<<<grid_size, block_size>>>(
        x.data_ptr<float>(),
        w.data_ptr<float>(),
        b.data_ptr<float>(),
        out.data_ptr<float>(),
        batch_size,
        in_features,
        out_features,
        divisor
    );
    return out;
}
"""

custom_cpp_source = r"""
torch::Tensor linear_relu_div_cuda(
    torch::Tensor x,
    torch::Tensor w,
    torch::Tensor b,
    float divisor
);
"""

fast_op = load_inline(
    name="fast_linear_relu_div",
    cpp_sources=custom_cpp_source,
    cuda_sources=custom_cuda_source,
    functions=["linear_relu_div_cuda"],
    verbose=False
)


class ModelNew(nn.Module):
    def __init__(self, in_features, out_features, divisor):
        super(ModelNew, self).__init__()
        self.in_features = in_features
        self.out_features = out_features
        self.divisor = divisor

        self.weight = nn.Parameter(torch.empty(out_features, in_features))
        self.bias = nn.Parameter(torch.empty(out_features))

        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        fan_in, _ = nn.init._calculate_fan_in_and_fan_out(self.weight)
        bound = 1 / math.sqrt(fan_in)
        nn.init.uniform_(self.bias, -bound, bound)

    def forward(self, x):
        return fast_op.linear_relu_div_cuda(x, self.weight, self.bias, self.divisor)
